<template>
  <DateRangePicker
    id="date_range"
    v-model:open="isOpen"
    v-model:value="dateRangeLocal"
    button-class="w-full"
    :clear-button="clearButton"
    @update:value="onChange"
  />
</template>
<script setup lang="ts">
import { type DateRange } from 'reka-ui';
import { differenceInDays, isBefore } from 'date-fns';
import { dateRangeData } from '~/constants/dateRangeSelector'; //mb move it to props

interface Props {
  label?: string;
  value: { start: string | null; end: string | null } | null;
  placeholder?: string;
  propertyNames: { start: string; end: string };
  preHardcodedPropertyName?: string;
  changePage?: boolean;
  clearButton?: boolean;
}
const props = withDefaults(defineProps<Props>(), {
  placeholder: 'Select date range',
  changePage: true,
  preHardcodedPropertyName: undefined,
  label: undefined,
  clearButton: false,
});
const route = useRoute();
const isOpen = ref<boolean>(false);

const dateRangeLocal = computed<DateRange | undefined>(() => {
  return props.value ? processDateRangeValue(props.value) || undefined : undefined;
});

async function onChange(value: DateRange | null) {
  const start = value?.start ? value.start.toString() : null;
  const end = value?.end ? value.end.toString() : null;
  const today = new Date();
  if ((start && !end) || (!start && end)) return;
  let preHardcodedQueryValue: string | undefined;
  if (props.preHardcodedPropertyName && start && end && isBefore(end, today)) {
    const daysDiff = differenceInDays(today, start);
    const preHardcodedEntry = Object.entries(dateRangeData);
    const entry = preHardcodedEntry.find(([_, data]) => data.daysGap === daysDiff);
    if (entry) preHardcodedQueryValue = entry[0];
  }

  await navigateTo({
    name: route.name,
    params: route.params,
    query: {
      ...route.query,
      ...(props.changePage && { page: 1 }),
      [props.propertyNames.start]: start || undefined,
      [props.propertyNames.end]: end || undefined,
      ...(props.preHardcodedPropertyName && {
        [props.preHardcodedPropertyName]:
          !start && !end
            ? props.preHardcodedPropertyName && route.query[props.preHardcodedPropertyName] !== 'custom'
              ? route.query[props.preHardcodedPropertyName]
              : 'last_7_days'
            : preHardcodedQueryValue
              ? preHardcodedQueryValue
              : 'custom',
      }),
    },
  });
}
</script>
